// HasAsset applies the HasEdge predicate on the "asset" edge.
func HasAsset() predicate.MediaProcessingJob {
	return predicate.MediaProcessingJob(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, AssetTable, AssetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAssetWith applies the HasEdge predicate on the "asset" edge with a given conditions (other predicates).
func HasAssetWith(preds ...predicate.MediaAsset) predicate.MediaProcessingJob {
	return predicate.MediaProcessingJob(func(s *sql.Selector) {
		step := newAssetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MediaProcessingJob) predicate.MediaProcessingJob {
	return predicate.MediaProcessingJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MediaProcessingJob) predicate.MediaProcessingJob {
	return predicate.MediaProcessingJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MediaProcessingJob) predicate.MediaProcessingJob {
	return predicate.MediaProcessingJob(sql.NotPredicates(p))
}
